```
function render() {
  const list = document.querySelector('.todo-list');
  list.innerHTML = '';
  const remaining = todos.filter(t => !t.completed).length;
  todos.forEach(todo => {
    const li = document.createElement('li');
    li.dataset.id = todo.id;
    if (todo.completed) li.classList.add('completed');
    if (currentlyEditing === todo.id) li.classList.add('editing');
    if (!matchesFilter(todo)) li.classList.add('hidden');
    // view
    const view = document.createElement('div'); view.className='view';
    const toggle = document.createElement('input'); toggle.className='toggle'; toggle.type='checkbox'; toggle.checked = todo.completed;
    toggle.addEventListener('change', () => { todo.completed = toggle.checked; save(); render(); });
    const label = document.createElement('label'); label.textContent = todo.title;
    label.addEventListener('dblclick', () => enterEdit(todo));
    const destroy = document.createElement('button'); destroy.className='destroy';
    destroy.addEventListener('click', () => { todos = todos.filter(t=>t.id!==todo.id); save(); render(); });
    view.append(toggle, label, destroy);
    // edit input
    const edit = document.createElement('input'); edit.className='edit'; edit.value = todo.title;
    edit.addEventListener('keydown', e => {
       if (e.key === 'Enter') { commitEdit(todo, edit.value); }
       else if (e.key === 'Escape') { cancelEdit(); }
    });
    edit.addEventListener('blur', () => { commitEdit(todo, edit.value); });
    li.append(view, edit);
    list.appendChild(li);
  });
  // main/footer visibility
  const hasTodos = todos.length > 0;
  document.querySelector('.main').classList.toggle('hidden', !hasTodos);
  document.querySelector('.footer').classList.toggle('hidden', !hasTodos);
  // toggle-all
  const toggleAll = document.getElementById('toggle-all');
  toggleAll.checked = todos.length>0 && todos.every(t=>t.completed);
  // counter
  const count = remaining;
  const countEl = document.querySelector('.todo-count');
  countEl.innerHTML = '';
  const strong = document.createElement('strong'); strong.textContent = String(count);
  countEl.appendChild(strong);
  countEl.appendChild(document.createTextNode(count===1?' item left':' items left'));
  // clear completed
  const clearBtn = document.querySelector('.clear-completed');
  clearBtn.classList.toggle('hidden', todos.every(t=>!t.completed));
  // filters
  updateFilterLinks();
}
```

