const fs = require('node:fs');
const path = require('node:path');
const { Window } = require('happy-dom');

const ROOT = path.resolve(__dirname, '..');
const INDEX_HTML = path.join(ROOT, 'assets', 'app-template.index.html');
const APP_JS = path.join(ROOT, 'js', 'app.js');

const STORAGE_KEY = 'todos-vanilla';
const FILTER_KEY = 'todos-vanilla-filter';

// TodoMVC verification world: drives the durable asset HTML through a real
// happy-dom window and exercises the production seam at js/app.js.
class TodoWorld {
  constructor() {
    this.newWindow();
  }

  newWindow() {
    this.window = new Window({ url: 'https://localhost/' });
  }

  get document() {
    return this.window.document;
  }

  // Load the durable template markup (scripts stripped; the production app is
  // evaluated explicitly) and run the production seam against it.
  loadAppSource() {
    const html = fs.readFileSync(INDEX_HTML, 'utf-8');
    const stripped = html.replace(/<script[\s\S]*?<\/script>/g, '');
    this.window.document.write(stripped);
    const src = fs.readFileSync(APP_JS, 'utf-8');
    this.window.eval(src);
  }

  seed(todos) {
    this.window.localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  // Cold start of the app with an optional pre-existing todo set.
  mount(todos) {
    this.newWindow();
    if (Array.isArray(todos) && todos.length) {
      this.seed(todos);
    } else {
      this.window.localStorage.removeItem(STORAGE_KEY);
    }
    this.loadAppSource();
  }

  // Simulate a browser reload: fresh DOM, same origin localStorage, same route.
  reload() {
    const saved = this.window.localStorage.getItem(STORAGE_KEY);
    const savedFilter = this.window.localStorage.getItem(FILTER_KEY);
    const hash = this.window.location.hash;
    this.newWindow();
    if (saved !== null) this.window.localStorage.setItem(STORAGE_KEY, saved);
    if (savedFilter !== null) this.window.localStorage.setItem(FILTER_KEY, savedFilter);
    this.window.location.hash = hash || '';
    this.loadAppSource();
  }

  // --- queries ---
  visibleTodos() {
    return Array.from(this.document.querySelectorAll('.todo-list li'))
      .filter((li) => !li.classList.contains('hidden'));
  }

  findLiByTitle(title) {
    return Array.from(this.document.querySelectorAll('.todo-list li'))
      .find((li) => {
        const label = li.querySelector('label');
        return label && label.textContent.trim() === title;
      });
  }

  filterLink(name) {
    const route = { All: '#/', Active: '#/active', Completed: '#/completed' }[name];
    return Array.from(this.document.querySelectorAll('.filters a'))
      .find((a) => a.getAttribute('href') === route);
  }

  // --- actions ---
  addTodo(title) {
    const input = this.document.querySelector('.new-todo');
    input.value = title;
    input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
  }

  toggleTodo(title) {
    const li = this.findLiByTitle(title);
    const toggle = li.querySelector('.toggle');
    toggle.checked = !toggle.checked;
    toggle.dispatchEvent(new this.window.Event('change', { bubbles: true }));
  }

  completeTodo(title) {
    const li = this.findLiByTitle(title);
    const toggle = li.querySelector('.toggle');
    if (!toggle.checked) {
      toggle.checked = true;
      toggle.dispatchEvent(new this.window.Event('change', { bubbles: true }));
    }
  }

  toggleAll() {
    const ta = this.document.getElementById('toggle-all');
    ta.checked = !ta.checked;
    ta.dispatchEvent(new this.window.Event('change', { bubbles: true }));
  }

  clickClearCompleted() {
    this.document.querySelector('.clear-completed')
      .dispatchEvent(new this.window.MouseEvent('click', { bubbles: true }));
  }

  enterEdit(title) {
    const li = this.findLiByTitle(title);
    const label = li.querySelector('label');
    label.dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
  }

  editTodo(title, value, commit) {
    this.enterEdit(title);
    const li = this.findLiByTitle(title);
    const edit = li.querySelector('.edit');
    edit.value = value;
    if (commit === 'Enter') {
      edit.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
    } else if (commit === 'Escape') {
      edit.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
    } else if (commit === 'blur') {
      edit.dispatchEvent(new this.window.Event('blur', { bubbles: true }));
    }
  }

  openFilter(name) {
    const route = { All: '#/', Active: '#/active', Completed: '#/completed' }[name];
    this.window.location.hash = route;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }
}

module.exports = { TodoWorld, STORAGE_KEY };

const assert = require('node:assert');
const { Given, When, Then } = require('@cucumber/cucumber');
const { TodoWorld } = require('./world');

Given('the app loads with no todos', function () {
  this.mount();
});

Given('the app loads with the following todos:', function (dataTable) {
  const rows = dataTable.hashes();
  const todos = rows.map((row, i) => ({
    id: i + 1,
    title: row.title,
    completed: row.completed === 'true',
  }));
  this.mount(todos);
});

When('I enter {string} in the new todo input and press Enter', function (title) {
  this.addTodo(title);
});

When('I toggle the todo {string}', function (title) {
  this.toggleTodo(title);
});

When('I toggle the toggle-all checkbox', function () {
  this.toggleAll();
});

When('I complete the todo {string}', function (title) {
  this.completeTodo(title);
});

When('I click the clear completed button', function () {
  this.clickClearCompleted();
});

When('I double-click the label of {string}', function (title) {
  this.enterEdit(title);
});

When('I edit the todo {string} to {string} and press Enter', function (title, value) {
  this.editTodo(title, value, 'Enter');
});

When('I edit the todo {string} to {string} and press Escape', function (title, value) {
  this.editTodo(title, value, 'Escape');
});

When('I edit the todo {string} to {string} and blur the input', function (title, value) {
  this.editTodo(title, value, 'blur');
});

When('I open the {string} filter', function (name) {
  this.openFilter(name);
});

When('I reload the app', function () {
  this.reload();
});

Then('the main section is hidden', function () {
  const main = this.document.querySelector('.main');
  assert.ok(main.classList.contains('hidden'), 'expected .main to be hidden');
});

Then('the footer is hidden', function () {
  const footer = this.document.querySelector('.footer');
  assert.ok(footer.classList.contains('hidden'), 'expected .footer to be hidden');
});

Then('the new todo input is focused', function () {
  const input = this.document.querySelector('.new-todo');
  assert.strictEqual(this.document.activeElement, input, 'expected new-todo input to be focused');
});

Then('the todo list shows {int} items', function (count) {
  assert.strictEqual(
    this.visibleTodos().length,
    count,
    `expected ${count} visible todo items, saw ${this.visibleTodos().length}`,
  );
});

Then('the item titled {string} is present', function (title) {
  const li = this.findLiByTitle(title);
  assert.ok(li, `expected an item titled "${title}" to be present`);
  assert.ok(!li.classList.contains('hidden'), `expected item "${title}" to be visible`);
});

Then('the todo {string} has a destroy button', function (title) {
  const li = this.findLiByTitle(title);
  assert.ok(li, `expected an item titled "${title}"`);
  assert.ok(li.querySelector('.destroy'), `expected "${title}" to expose a destroy button`);
});

Then('the todo {string} is marked completed', function (title) {
  const li = this.findLiByTitle(title);
  assert.ok(li, `expected an item titled "${title}"`);
  assert.ok(li.classList.contains('completed'), `expected "${title}" to be marked completed`);
});

Then('the toggle-all checkbox is checked', function () {
  const ta = this.document.getElementById('toggle-all');
  assert.ok(ta.checked, 'expected toggle-all checkbox to be checked');
});

Then('the toggle-all checkbox is unchecked', function () {
  const ta = this.document.getElementById('toggle-all');
  assert.ok(!ta.checked, 'expected toggle-all checkbox to be unchecked');
});

Then('the todo {string} is in editing mode', function (title) {
  const li = this.findLiByTitle(title);
  assert.ok(li, `expected an item titled "${title}"`);
  assert.ok(li.classList.contains('editing'), `expected "${title}" to be in editing mode`);
});

Then('the todo {string} is not in editing mode', function (title) {
  const li = this.findLiByTitle(title);
  assert.ok(li, `expected an item titled "${title}"`);
  assert.ok(!li.classList.contains('editing'), `expected "${title}" to not be in editing mode`);
});

Then('the edit input of {string} is focused', function (title) {
  const li = this.findLiByTitle(title);
  assert.ok(li, `expected an item titled "${title}"`);
  const edit = li.querySelector('.edit');
  assert.ok(edit, `expected "${title}" to expose an edit input`);
  assert.strictEqual(this.document.activeElement, edit, `expected the edit input of "${title}" to be focused`);
});

Then('the counter reads {string}', function (text) {
  const count = this.document.querySelector('.todo-count');
  const actual = count.textContent.replace(/\s+/g, ' ').trim();
  assert.strictEqual(actual, text, `expected counter to read "${text}", saw "${actual}"`);
});

Then('the counter number is wrapped in a strong element', function () {
  const strong = this.document.querySelector('.todo-count strong');
  assert.ok(strong, 'expected the counter number to be wrapped in a strong element');
});

Then('the clear completed button is hidden', function () {
  const btn = this.document.querySelector('.clear-completed');
  assert.ok(btn.classList.contains('hidden'), 'expected clear-completed button to be hidden');
});

Then('the localStorage key {string} holds a JSON array of objects', function (key) {
  const raw = this.window.localStorage.getItem(key);
  assert.ok(raw !== null, `expected localStorage key "${key}" to exist`);
  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    assert.fail(`localStorage key "${key}" is not valid JSON: ${e.message}`);
  }
  assert.ok(Array.isArray(parsed), `expected localStorage key "${key}" to hold an array`);
});

Then(
  'every object in that array has the string keys {string}, {string}, and {string}',
  function (k1, k2, k3) {
    const raw = this.window.localStorage.getItem('todos-vanilla');
    const parsed = JSON.parse(raw);
    parsed.forEach((obj, i) => {
      [k1, k2, k3].forEach((key) => {
        assert.ok(
          Object.prototype.hasOwnProperty.call(obj, key),
          `array item ${i} is missing key "${key}"`,
        );
      });
    });
  },
);

Then('the {string} filter link is selected', function (name) {
  const link = this.filterLink(name);
  assert.ok(link, `expected a "${name}" filter link`);
  assert.ok(link.classList.contains('selected'), `expected the "${name}" filter link to be selected`);
});

