/**
 * TodoMVC production seam.
 *
 * Loaded by the verification world after the durable template markup is present
 * in the document. Maintains todo state in localStorage under the key the
 * scenario contract requires ("todos-vanilla") and renders behaviour through the
 * standard TodoMVC DOM contract (classes: hidden, completed, editing,
 * selected; selectors: .new-todo, .todo-list, .toggle, .toggle-all,
 * .todo-count, .clear-completed, .filters a, .destroy, .edit).
 */
(function () {
  'use strict';

  var STORAGE_KEY = 'todos-vanilla';
  var FILTER_KEY = 'todos-vanilla-filter';

  var todos = [];
  var filter = 'all';
  var currentlyEditing = null;

  var newTodoInput = document.querySelector('.new-todo');
  var list = document.querySelector('.todo-list');
  var toggleAll = document.getElementById('toggle-all');
  var clearCompleted = document.querySelector('.clear-completed');
  var countEl = document.querySelector('.todo-count');

  /** @planks("the app loads with no todos") */
  /** @planks("the app loads with the following todos:") */
  function load() {
    var raw = localStorage.getItem(STORAGE_KEY);
    todos = raw ? JSON.parse(raw) : [];
    filter = localStorage.getItem(FILTER_KEY) || 'all';
  }

  function save() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
    localStorage.setItem(FILTER_KEY, filter);
  }

  function nextId() {
    var max = 0;
    todos.forEach(function (t) {
      if (t.id > max) max = t.id;
    });
    return max + 1;
  }

  function matchesFilter(todo) {
    if (filter === 'active') return !todo.completed;
    if (filter === 'completed') return todo.completed;
    return true;
  }

  function visibleCount() {
    return todos.filter(function (t) {
      return !t.completed;
    }).length;
  }

  function updateFilterLinks() {
    var links = document.querySelectorAll('.filters a');
    Array.prototype.forEach.call(links, function (a) {
      var href = a.getAttribute('href');
      var f = 'all';
      if (href === '#/active') f = 'active';
      else if (href === '#/completed') f = 'completed';
      a.classList.toggle('selected', f === filter);
    });
  }

  function render() {
    list.innerHTML = '';
    todos.forEach(function (todo) {
      var li = document.createElement('li');
      li.dataset.id = String(todo.id);
      if (todo.completed) li.classList.add('completed');
      if (currentlyEditing === todo.id) li.classList.add('editing');
      if (!matchesFilter(todo)) li.classList.add('hidden');

      var view = document.createElement('div');
      view.className = 'view';

      var toggle = document.createElement('input');
      toggle.type = 'checkbox';
      toggle.className = 'toggle';
      toggle.checked = !!todo.completed;
      /** @planks("I toggle the todo {string}") */
      /** @planks("I complete the todo {string}") */
      toggle.addEventListener('change', function () {
        todo.completed = toggle.checked;
        save();
        render();
      });

      var label = document.createElement('label');
      label.textContent = todo.title;
      /** @planks("I double-click the label of {string}") */
      label.addEventListener('dblclick', function () {
        enterEdit(todo);
      });

      var destroy = document.createElement('button');
      destroy.className = 'destroy';
      destroy.addEventListener('click', function () {
        todos = todos.filter(function (t) {
          return t.id !== todo.id;
        });
        save();
        render();
      });

      view.appendChild(toggle);
      view.appendChild(label);
      view.appendChild(destroy);

      var edit = document.createElement('input');
      edit.type = 'text';
      edit.className = 'edit';
      edit.value = todo.title;
      /** @planks("I edit the todo {string} to {string} and press Enter") */
      /** @planks("I edit the todo {string} to {string} and press Escape") */
      /** @planks("I edit the todo {string} to {string} and blur the input") */
      edit.addEventListener('keydown', function (e) {
        if (e.key === 'Enter') {
          commitEdit(todo, edit.value);
        } else if (e.key === 'Escape') {
          cancelEdit();
        }
      });
      edit.addEventListener('blur', function () {
        commitEdit(todo, edit.value);
      });

      li.appendChild(view);
      li.appendChild(edit);
      list.appendChild(li);
    });

    var hasTodos = todos.length > 0;
    document.querySelector('.main').classList.toggle('hidden', !hasTodos);
    document.querySelector('.footer').classList.toggle('hidden', !hasTodos);

    toggleAll.checked = hasTodos && todos.every(function (t) {
      return t.completed;
    });

    countEl.innerHTML = '';
    var strong = document.createElement('strong');
    strong.textContent = String(visibleCount());
    countEl.appendChild(strong);
    countEl.appendChild(
      document.createTextNode(visibleCount() === 1 ? ' item left' : ' items left'),
    );

    clearCompleted.classList.toggle(
      'hidden',
      todos.every(function (t) {
        return !t.completed;
      }),
    );

    updateFilterLinks();
  }

  function liForId(id) {
    var items = document.querySelectorAll('.todo-list li');
    for (var i = 0; i < items.length; i++) {
      if (items[i].dataset.id === String(id)) return items[i];
    }
    return null;
  }

  function enterEdit(todo) {
    currentlyEditing = todo.id;
    render();
    var li = liForId(todo.id);
    if (li) {
      var edit = li.querySelector('.edit');
      edit.focus();
      if (edit.setSelectionRange) {
        edit.setSelectionRange(edit.value.length, edit.value.length);
      }
    }
  }

  function commitEdit(todo, value) {
    if (currentlyEditing !== todo.id) return;
    var trimmed = (value || '').trim();
    if (trimmed === '') {
      todos = todos.filter(function (t) {
        return t.id !== todo.id;
      });
    } else {
      todo.title = trimmed;
    }
    currentlyEditing = null;
    save();
    render();
  }

  function cancelEdit() {
    currentlyEditing = null;
    render();
  }

  /** @planks("I enter {string} in the new todo input and press Enter") */
  function onNewTodoKeydown(e) {
    if (e.key !== 'Enter') return;
    var value = newTodoInput.value.trim();
    if (value !== '') {
      todos.push({ id: nextId(), title: value, completed: false });
      save();
    }
    newTodoInput.value = '';
    render();
    newTodoInput.focus();
  }

  /** @planks("I toggle the toggle-all checkbox") */
  function onToggleAllChange() {
    var checked = toggleAll.checked;
    todos.forEach(function (t) {
      t.completed = checked;
    });
    save();
    render();
  }

  /** @planks("I click the clear completed button") */
  function onClearCompletedClick() {
    todos = todos.filter(function (t) {
      return !t.completed;
    });
    save();
    render();
  }

  function applyRouteFromHash() {
    var h = window.location.hash;
    if (h === '#/active') filter = 'active';
    else if (h === '#/completed') filter = 'completed';
    else filter = 'all';
  }

  /** @planks("I open the {string} filter") */
  /** @planks("I reload the app") */
  function onHashChange() {
    applyRouteFromHash();
    save();
    render();
  }

  function init() {
    load();
    applyRouteFromHash();
    newTodoInput.addEventListener('keydown', onNewTodoKeydown);
    toggleAll.addEventListener('change', onToggleAllChange);
    clearCompleted.addEventListener('click', onClearCompletedClick);
    window.addEventListener('hashchange', onHashChange);
    render();
    newTodoInput.focus();
  }

  init();
})();
